/// <summary>
/// Builds the map of fields to copy between the source tmp table intance to the destination tmp table instance.
/// </summary>
/// <param name = "_copyMapBuilder">The instance of <c>CustAccountStatementExtDPTmpTableCopyMapBuilder</c> used to build the field map.</param>
protected void mapCustAccountStatementExtTmpToNewTempTableInstance(CustAccountStatementExtDPTmpTableCopyMapBuilder _copyMapBuilder)
{
    next mapCustAccountStatementExtTmpToNewTempTableInstance (_copyMapBuilder);
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGCompanyEmail));
    // MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021 - Start
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGBPayBillerCode));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGBPayReference));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGRegNum));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGBankAccountNum));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGRemittanceEmail));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGCustServiceNum));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGFooterNote));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGKnownAs));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGBsbReference)); 
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGCurrency));        
    // MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021 - End
}

    public void processReport()
    {
        next processReport();

        Date                        duedate1, duedate2, duedate3, duedate4, dateNull;
        AmountCur                   balanceDue1, balanceDue2, balanceDue3, balanceDue4;
        int                         flagValue = 0;
        CustAccountStatementExtTmp  custAccountStatementExtTmp = this.custAccountStatementExtTmpNew;

        dateNull = Global::DateNull();

        while select
            sum(CustTrans_Credit),
            sum(CustTrans_Debit),
            CustTrans_DueDate
        from
            custAccountStatementExtTmp
        group by
            CustTrans_DueDate
        where
            custAccountStatementExtTmp.CustTrans_DueDate != Global::DateNull()
        {
            flagValue++;

            if (flagValue == 1)
            {
                duedate1        = custAccountStatementExtTmp.CustTrans_DueDate;
                balanceDue1     = custAccountStatementExtTmp.CustTrans_Debit
                                    - custAccountStatementExtTmp.CustTrans_Credit;
            }

            if (flagValue == 2)
            {
                duedate2        = custAccountStatementExtTmp.CustTrans_DueDate;
                balanceDue2     = custAccountStatementExtTmp.CustTrans_Debit
                                    - custAccountStatementExtTmp.CustTrans_Credit;
            }

            if (flagValue == 3)
            {
                duedate3        = custAccountStatementExtTmp.CustTrans_DueDate;
                balanceDue3     = custAccountStatementExtTmp.CustTrans_Debit 
                                    - custAccountStatementExtTmp.CustTrans_Credit;
            }

            if (flagValue >= 4)
            {
                if (flagValue == 4)
                {
                    duedate4     = custAccountStatementExtTmp.CustTrans_DueDate;
                }
                balanceDue4     = custAccountStatementExtTmp.CustTrans_Debit
                                    - custAccountStatementExtTmp.CustTrans_Credit
                                    + balanceDue4;
            }
        }

        while select forupdate custAccountStatementExtTmp
        {
            if (custAccountStatementExtTmp.Balance01 != 0)
            {
                ttsbegin;
                custAccountStatementExtTmp.KPMGDueDate1     = duedate1;
                custAccountStatementExtTmp.KPMGBalanceDue1  = balanceDue1;
                custAccountStatementExtTmp.KPMGDueDate2     = duedate2;
                custAccountStatementExtTmp.KPMGBalanceDue2  = balanceDue2;
                custAccountStatementExtTmp.KPMGDueDate3     = duedate3;
                custAccountStatementExtTmp.KPMGBalanceDue3  = balanceDue3;
                custAccountStatementExtTmp.KPMGDueDate4     = duedate4;
                custAccountStatementExtTmp.KPMGBalanceDue4  = balanceDue4;
                custAccountStatementExtTmp.update();
                ttscommit;
            }
        }
    }
